import { assert, readonly } from './records.js';

// Save format v1's state.random is the complete lcg32 state. Keep this
// recurrence stable: changing it changes every existing save's continuation.
export function nextRandom(state) {
  state.random = (Math.imul(1664525, state.random) + 1013904223) >>> 0;
  return state.random / 4294967296;
}

// Only resolution hooks receive this capability. It cannot escape the call,
// mutate a committed snapshot later, or consume randomness during inspection.
export function callWithRandom(state, hook, context, fallback) {
  if (!hook) return fallback;
  let active = true;
  const rng = Object.freeze({ next: () => {
    assert(active, 'RNG capability expired outside resolution hook');
    return nextRandom(state);
  } });
  try {
    const result = hook(readonly(context), Object.freeze({ rng }));
    assert(!result?.then, 'Shell hooks must be synchronous');
    return result;
  } finally { active = false; }
}
